from __future__ import annotations

from dataclasses import dataclass

from .engine import EngineConfig, NeuronGraphRAG
from .sample import load_sample_corpus


@dataclass(frozen=True, slots=True)
class EvalCase:
    query: str
    expected_node_id: str


EVAL_CASES = (
    EvalCase(
        "The payment retry policy changed from two attempts to five attempts.",
        "decision",
    ),
    EvalCase(
        "Decision D17 accepted five payment attempts to reduce transient failures.",
        "implementation",
    ),
    EvalCase(
        "Pull request 42 implemented decision D17 in the payment worker.",
        "incident",
    ),
)


def evaluate(*, limit: int = 5) -> dict[str, object]:
    baseline = _run_cases(
        EngineConfig(
            entry_weight=1.0,
            graph_weight=0.0,
            seed_count=1,
            max_hops=2,
        ),
        limit,
    )
    graph = _run_cases(
        EngineConfig(
            entry_weight=0.25,
            graph_weight=0.75,
            seed_count=1,
            max_hops=2,
        ),
        limit,
    )
    improved_queries = sum(
        graph_rank < baseline_rank
        for graph_rank, baseline_rank in zip(
            graph["ranks"], baseline["ranks"], strict=True
        )
    )
    return {
        "corpus_size": len(loadable_document_ids()),
        "cases": len(EVAL_CASES),
        "baseline_hybrid": baseline,
        "graph_rag": graph,
        "improved_queries": improved_queries,
    }


def loadable_document_ids() -> tuple[str, ...]:
    from .sample import SAMPLE_DOCUMENTS

    return tuple(document[0] for document in SAMPLE_DOCUMENTS)


def _run_cases(config: EngineConfig, limit: int) -> dict[str, object]:
    ranks: list[int] = []
    with NeuronGraphRAG(config=config) as engine:
        load_sample_corpus(engine)
        for case in EVAL_CASES:
            trace = engine.search(case.query, limit=limit, now=1_000.0)
            rank = next(
                (
                    index
                    for index, hit in enumerate(trace.hits, start=1)
                    if hit.node.node_id == case.expected_node_id
                ),
                limit + 1,
            )
            ranks.append(rank)
    reciprocal_rank = sum(1.0 / rank for rank in ranks) / len(ranks)
    hit_at_three = sum(rank <= 3 for rank in ranks) / len(ranks)
    return {
        "mean_reciprocal_rank": reciprocal_rank,
        "hit_at_3": hit_at_three,
        "ranks": ranks,
    }

from __future__ import annotations

import hashlib
import json
from dataclasses import asdict, fields
from typing import Any, Mapping

from .evidence_feedback import EngineConfig, NeuronGraphRAG


FEEDBACK_CONFIG_FIELDS = (
    "feedback_learning_rate",
    "sibling_feedback_normalization",
    "maximum_edge_weight",
    "relation_feedback_evidence_quorum",
    "confirmed_outcome_reinforcement",
    "confirmation_decay_ratio",
    "soft_start_feedback_reinforcement",
    "soft_start_feedback_ratio",
    "outcome_driven_feedback_deactivation",
)
SEARCH_SURFACES = ("combined", "relation")


def config_fingerprint(value: Mapping[str, Any]) -> str:
    canonical = (
        json.dumps(dict(value), ensure_ascii=False, indent=2, sort_keys=True) + "\n"
    ).encode("utf-8")
    return "sha256:" + hashlib.sha256(canonical).hexdigest()


def effective_config(config: EngineConfig) -> dict[str, dict[str, Any]]:
    raw = asdict(config)
    names = {field.name for field in fields(EngineConfig)}
    if set(raw) != names:
        raise RuntimeError("EngineConfig serialization is incomplete")
    active_names = set(names)
    if (
        raw["soft_start_feedback_reinforcement"] is False
        and raw["soft_start_feedback_ratio"] is None
    ):
        active_names -= {
            "soft_start_feedback_reinforcement",
            "soft_start_feedback_ratio",
        }
    if raw["outcome_driven_feedback_deactivation"] is False:
        active_names.remove("outcome_driven_feedback_deactivation")
    return {
        "retrieval": {
            name: raw[name]
            for name in sorted(active_names - set(FEEDBACK_CONFIG_FIELDS))
        },
        "feedback": {
            name: raw[name]
            for name in sorted(set(FEEDBACK_CONFIG_FIELDS) & active_names)
        },
    }


def effective_config_provenance(config: EngineConfig) -> dict[str, Any]:
    value = effective_config(config)
    return {
        "effective_config": value,
        "retrieval_config_fingerprint": config_fingerprint(value["retrieval"]),
        "feedback_config_fingerprint": config_fingerprint(value["feedback"]),
        "full_config_fingerprint": config_fingerprint(value),
    }


def effective_search_surface(config: EngineConfig) -> str:
    if (
        config.confirmed_outcome_reinforcement
        or config.soft_start_feedback_reinforcement
        or config.sibling_feedback_normalization > 0.0
    ):
        return "relation"
    return "combined"


def search_with_surface(
    engine: NeuronGraphRAG,
    query: str,
    *,
    limit: int,
    search_surface: str,
    now: float | None = None,
) -> Any:
    if search_surface == "combined":
        return engine.search(query, limit=limit, now=now)
    if search_surface == "relation":
        return engine.search_channels(query, limit=limit, now=now).relation
    raise ValueError(f"unknown search surface: {search_surface}")
